import re
from decimal import Decimal, ROUND_HALF_UP

_UNITS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'wk': 604800, 'wks': 604800, 'week': 604800, 'weeks': 604800,
}

_NUM = r'\d+(?:\.\d+)?'
_COMPONENT = re.compile(r'\s*(' + _NUM + r')\s*([A-Za-z]+)\s*')
_ISO = re.compile(
    r'P(?:(' + _NUM + r')W)?(?:(' + _NUM + r')D)?'
    r'(?:T(?:(' + _NUM + r')H)?(?:(' + _NUM + r')M)?(?:(' + _NUM + r')S)?)?'
)
_INT = re.compile(r'\d+')


def _round(value: Decimal) -> int:
    return int(value.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def _num(s: str) -> Decimal:
    return Decimal(s)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    # Bare non-negative integer: seconds.
    if _INT.fullmatch(s):
        return int(s)

    # Clock notation: hh:mm:ss or mm:ss.
    if ':' in s:
        parts = s.split(':')
        if len(parts) not in (2, 3):
            raise ValueError(f"invalid clock duration: {text!r}")
        if not all(re.fullmatch(_NUM, p) for p in parts):
            raise ValueError(f"invalid clock duration: {text!r}")
        total = Decimal(0)
        for p in parts:
            total = total * 60 + _num(p)
        return _round(total)

    # ISO 8601 duration.
    if s.startswith('P'):
        m = _ISO.fullmatch(s)
        if not m or s == 'P' or s.endswith('T'):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        weeks, days, hours, mins, secs = m.groups()
        total = Decimal(0)
        for val, unit in ((weeks, 604800), (days, 86400), (hours, 3600),
                          (mins, 60), (secs, 1)):
            if val is not None:
                total += _num(val) * unit
        return _round(total)

    # Number+unit components, optionally separated by spaces.
    pos = 0
    total = Decimal(0)
    count = 0
    while pos < len(s):
        m = _COMPONENT.match(s, pos)
        if not m or m.end() == pos:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {m.group(2)!r} in {text!r}")
        total += _num(m.group(1)) * _UNITS[unit]
        count += 1
        pos = m.end()
    if count == 0:
        raise ValueError(f"invalid duration: {text!r}")
    return _round(total)

